            "docs.rules.t3": "签名算法",
            "docs.rules.s13": "对所有发送或接收的数据集合M中的非空参数，按照参数名ASCII码从小到大排序（字典序）。",
            "docs.rules.s14": "使用URL键值对格式（key1=value1&key2=value2…）拼接成字符串stringA。",
            "docs.rules.s15": "使用 hmac sha1 算法，用 商户签名密钥 对拼接成的字符串stringA进行加密stringB。",
            "docs.rules.s16": "将加密后的字符串stringB使用 Base64 进行编码。",
            "docs.rules.t4": "注意事项",
            "docs.rules.s17": "按参数名ASCII码从小到大排序（字典序）。",
